import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Expenses = () => {
  const [expenses, setExpenses] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    amount: '',
    category: 'Other',
    date: new Date().toISOString().split('T')[0],
    description: '',
  });

  useEffect(() => {
    loadExpenses();
    loadSummary();
  }, []);

  const loadExpenses = async () => {
    try {
      const res = await API.get('/expenses');
      setExpenses(res.data.data);
    } catch (error) {
      toast.error('Failed to load expenses');
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadSummary = async () => {
    try {
      const res = await API.get('/expenses/summary');
      setSummary(res.data.data);
    } catch (error) {
      console.error('Error loading summary:', error);
    }
  };

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await API.post('/expenses', formData);
      toast.success('Expense added successfully!');
      setShowModal(false);
      setFormData({ title: '', amount: '', category: 'Other', date: new Date().toISOString().split('T')[0], description: '' });
      loadExpenses();
      loadSummary();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to add expense');
      console.error('Error:', error);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this expense?')) return;
    try {
      await API.delete(`/expenses/${id}`);
      toast.success('Expense deleted successfully!');
      loadExpenses();
      loadSummary();
    } catch (error) {
      toast.error('Failed to delete expense');
      console.error('Error:', error);
    }
  };

  if (loading) {
    return <div className="loading">Loading expenses...</div>;
  }

  return (
    <div>
      <div style={styles.header}>
        <h2 style={styles.pageTitle}>Expenses</h2>
        <button style={styles.addBtn} onClick={() => setShowModal(true)}>
          ➕ Add Expense
        </button>
      </div>

      {/* Summary Cards */}
      {summary && (
        <div style={styles.summaryGrid}>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>Total Expenses</div>
            <div style={styles.summaryValue}>PKR {summary.totalExpenses?.toLocaleString() || 0}</div>
          </div>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>This Month</div>
            <div style={styles.summaryValue}>PKR {summary.monthlyExpenses?.toLocaleString() || 0}</div>
          </div>
          <div style={styles.summaryCard}>
            <div style={styles.summaryLabel}>Transactions</div>
            <div style={styles.summaryValue}>{summary.totalTransactions || 0}</div>
          </div>
          {summary.categories && Object.keys(summary.categories).length > 0 && (
            <div style={styles.summaryCard}>
              <div style={styles.summaryLabel}>Top Category</div>
              <div style={styles.summaryValue}>
                {Object.keys(summary.categories).reduce((a, b) => summary.categories[a] > summary.categories[b] ? a : b)}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Expenses Table */}
      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>#</th>
              <th>Title</th>
              <th>Category</th>
              <th>Amount</th>
              <th>Date</th>
              <th>Description</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {expenses.length === 0 ? (
              <tr><td colSpan="7" style={{ textAlign: 'center', padding: '30px', color: '#6b7f99' }}>No expenses recorded</td></tr>
            ) : (
              expenses.map((e, index) => (
                <tr key={e._id}>
                  <td>{index + 1}</td>
                  <td><strong>{e.title}</strong></td>
                  <td><span style={styles.categoryBadge}>{e.category}</span></td>
                  <td style={{ color: '#dc3545', fontWeight: '600' }}>PKR {e.amount.toLocaleString()}</td>
                  <td>{new Date(e.date).toLocaleDateString()}</td>
                  <td style={{ color: '#6b7f99', fontSize: '12px' }}>{e.description || '—'}</td>
                  <td>
                    <button style={{ ...styles.actionBtn, color: '#dc3545' }} onClick={() => handleDelete(e._id)}>🗑️</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Modal */}
      {showModal && (
        <div style={styles.modalOverlay} onClick={() => setShowModal(false)}>
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h3 style={styles.modalTitle}>💰 Add Expense</h3>
            <form onSubmit={handleSubmit}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Title *</label>
                <input
                  type="text"
                  name="title"
                  value={formData.title}
                  onChange={handleInputChange}
                  style={styles.input}
                  required
                  placeholder="e.g., Internet Bill"
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Amount (PKR) *</label>
                <input
                  type="number"
                  name="amount"
                  value={formData.amount}
                  onChange={handleInputChange}
                  style={styles.input}
                  required
                  min="1"
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Category</label>
                <select
                  name="category"
                  value={formData.category}
                  onChange={handleInputChange}
                  style={styles.input}
                >
                  <option value="Utilities">Utilities</option>
                  <option value="Salaries">Salaries</option>
                  <option value="Equipment">Equipment</option>
                  <option value="Maintenance">Maintenance</option>
                  <option value="Marketing">Marketing</option>
                  <option value="Office">Office</option>
                  <option value="Internet">Internet</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Date</label>
                <input
                  type="date"
                  name="date"
                  value={formData.date}
                  onChange={handleInputChange}
                  style={styles.input}
                />
              </div>
              <div style={styles.formGroup}>
                <label style={styles.label}>Description</label>
                <input
                  type="text"
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  style={styles.input}
                  placeholder="Optional description..."
                />
              </div>
              <div style={styles.modalActions}>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowModal(false)}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>Add Expense</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '20px',
    flexWrap: 'wrap',
    gap: '12px',
  },
  pageTitle: {
    fontSize: '22px',
    fontWeight: '700',
    color: '#1a2a3a',
    margin: 0,
  },
  addBtn: {
    padding: '10px 24px',
    background: '#fd7e14',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.2s',
  },
  summaryGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
    gap: '16px',
    marginBottom: '24px',
  },
  summaryCard: {
    background: 'white',
    padding: '16px 20px',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
  },
  summaryLabel: {
    fontSize: '12px',
    color: '#6b7f99',
    textTransform: 'uppercase',
    fontWeight: '500',
  },
  summaryValue: {
    fontSize: '24px',
    fontWeight: '700',
    color: '#1a2a3a',
    marginTop: '4px',
  },
  tableContainer: {
    background: 'white',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
    overflow: 'hidden',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    fontSize: '13px',
  },
  categoryBadge: {
    display: 'inline-block',
    padding: '2px 10px',
    borderRadius: '12px',
    background: '#e9eef4',
    fontSize: '11px',
    fontWeight: '500',
  },
  actionBtn: {
    background: 'none',
    border: 'none',
    fontSize: '16px',
    cursor: 'pointer',
    padding: '4px 8px',
  },
  modalOverlay: {
    position: 'fixed',
    inset: 0,
    background: 'rgba(0,0,0,0.5)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000,
    backdropFilter: 'blur(4px)',
  },
  modal: {
    background: 'white',
    borderRadius: '20px',
    padding: '32px',
    width: '500px',
    maxWidth: '95%',
    maxHeight: '90vh',
    overflow: 'auto',
  },
  modalTitle: {
    fontSize: '20px',
    marginBottom: '20px',
    color: '#1a2a3a',
  },
  formGroup: {
    marginBottom: '16px',
  },
  label: {
    fontWeight: '500',
    marginBottom: '4px',
    fontSize: '14px',
    color: '#1a2a3a',
    display: 'block',
  },
  input: {
    width: '100%',
    padding: '10px 14px',
    border: '2px solid #e2eaf2',
    borderRadius: '10px',
    fontSize: '14px',
    boxSizing: 'border-box',
  },
  modalActions: {
    display: 'flex',
    gap: '12px',
    marginTop: '20px',
    justifyContent: 'flex-end',
  },
  cancelBtn: {
    padding: '10px 24px',
    background: '#e9eef4',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '500',
    cursor: 'pointer',
  },
  saveBtn: {
    padding: '10px 24px',
    background: '#fd7e14',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
  },
};

export default Expenses;
